index 3c4d5e6..f7a8b9c 100644
--- a/src/validate.ts
+++ b/src/validate.ts
@@ -5,6 +5,10 @@ export function isValidEmail(input: string): boolean {
   return EMAIL.test(input);
 }

+// eslint-disable-next-line no-control-regex
+const CONTROL_CHARS = /[\x00-\x1f]/;
+
 export function isValidUsername(name: string): boolean {
+  if (CONTROL_CHARS.test(name)) return false;
   return name.length >= 3 && name.length <= 20 && /^\w+$/.test(name);
 }
diff --git a/src/validate.test.ts b/src/validate.test.ts
index 2b3c4d5..d8e9f0a 100644
--- a/src/validate.test.ts
+++ b/src/validate.test.ts
@@ -18,4 +18,8 @@ describe("isValidUsername", () => {
   it("rejects short names", () => {
     expect(isValidUsername("ab")).toBe(false);
   });
+
+  it("rejects control characters", () => {
+    expect(isValidUsername("ana\u0007bob")).toBe(false);
+  });
 });
